1	"use server";
2	
3	import { z } from "zod";
4	import { revalidatePath } from "next/cache";
5	import { requireRole } from "@/lib/auth";
6	import { createClient } from "@/lib/supabase/server";
7	import { getPayments } from "@/lib/integrations/payments";
8	import { cancellationOutcome } from "@/lib/pricing";
9	
10	const uuid = z.string().uuid();
11	
12	/** Save a listener to the customer's favorites (idempotent). */
13	export async function addFavorite(
14	  providerId: string,
15	): Promise<{ ok: boolean }> {
16	  const profile = await requireRole("customer");
17	  if (!uuid.safeParse(providerId).success) return { ok: false };
18	  const supabase = await createClient();
19	  const { error } = await supabase
20	    .from("favorites")
21	    .upsert(
22	      { customer_id: profile.id, provider_id: providerId },
23	      { onConflict: "customer_id,provider_id", ignoreDuplicates: true },
24	    );
25	  if (error) return { ok: false };
26	  revalidatePath("/account");
27	  return { ok: true };
28	}
29	
30	/** Remove a listener from the customer's favorites. */
31	export async function removeFavorite(
32	  providerId: string,
33	): Promise<{ ok: boolean }> {
34	  const profile = await requireRole("customer");
35	  const supabase = await createClient();
36	  const { error } = await supabase
37	    .from("favorites")
38	    .delete()
39	    .eq("customer_id", profile.id)
40	    .eq("provider_id", providerId);
41	  if (error) return { ok: false };
42	  revalidatePath("/account");
43	  return { ok: true };
44	}
45	
46	export interface CancelResult {
47	  ok: boolean;
48	  released?: boolean;
49	  error?: string;
50	}
51	
52	/**
53	 * Cancel a confirmed booking. Cancellation policy (SPEC §5): a scheduled session
54	 * cancelled ≥1h before its start releases the hold, otherwise the block is
55	 * charged. A "now" booking that was never joined releases (the customer never
56	 * talked — "you're in control, leave any time"). Capture/refund go through the
57	 * payments adapter.
58	 */
59	export async function cancelBooking(bookingId: string): Promise<CancelResult> {
60	  const profile = await requireRole("customer");
61	  const supabase = await createClient();
62	
63	  const { data: booking } = await supabase
64	    .from("bookings")
65	    .select("*")
66	    .eq("id", bookingId)
67	    .maybeSingle();
68	  if (!booking || booking.customer_id !== profile.id) {
69	    return { ok: false, error: "Booking not found." };
70	  }
71	  if (booking.status !== "confirmed") {
72	    return { ok: false, error: "This booking can't be cancelled." };
73	  }
74	
75	  let release: boolean;
76	  if (booking.start_mode === "scheduled") {
77	    release =
78	      cancellationOutcome({
79	        priceBlockCents: booking.price_block_cents,
80	        scheduledAt: booking.scheduled_at,
81	        nowMs: Date.now(),
82	      }).action === "release";
83	  } else {
84	    release = true; // a "now" booking that was never joined
85	  }
86	
87	  const payments = getPayments();
88	  if (booking.payment_ref) {
89	    if (release) {
90	      await payments.refund({
91	        paymentRef: booking.payment_ref,
92	        amountCents: booking.price_block_cents,
93	      });
94	    } else {
95	      await payments.capture({
96	        paymentRef: booking.payment_ref,
97	        amountCents: booking.price_block_cents,
98	      });
99	    }
100	  }
101	
102	  const { error } = await supabase
103	    .from("bookings")
104	    .update({ status: "cancelled" })
105	    .eq("id", bookingId);
106	  if (error) return { ok: false, error: "Could not cancel the booking." };
107	
108	  revalidatePath("/account");
109	  return { ok: true, released: release };
110	}
111	
112	const rescheduleSchema = z.object({
113	  bookingId: uuid,
114	  scheduledAt: z.string().datetime(),
115	});
116	
117	/** Move a confirmed booking to a new future time. */
118	export async function rescheduleBooking(input: {
119	  bookingId: string;
120	  scheduledAt: string;
121	}): Promise<{ ok: boolean; error?: string }> {
122	  const profile = await requireRole("customer");
123	  const parsed = rescheduleSchema.safeParse(input);
124	  if (!parsed.success) return { ok: false, error: "Pick a valid time." };
125	  if (new Date(parsed.data.scheduledAt).getTime() <= Date.now()) {
126	    return { ok: false, error: "Pick a time in the future." };
127	  }
128	
129	  const supabase = await createClient();
130	  const { error } = await supabase
131	    .from("bookings")
132	    .update({
133	      scheduled_at: parsed.data.scheduledAt,
134	      start_mode: "scheduled",
135	    })
136	    .eq("id", parsed.data.bookingId)
137	    .eq("customer_id", profile.id)
138	    .eq("status", "confirmed");
139	  if (error) return { ok: false, error: "Could not reschedule." };
140	
141	  revalidatePath("/account");
142	  return { ok: true };
143	}
144	
145	/** Update the customer's display name. */
146	export async function updateProfileName(
147	  name: string,
148	): Promise<{ ok: boolean; error?: string }> {
149	  const profile = await requireRole("customer");
150	  const trimmed = name.trim();
151	  if (trimmed.length < 1 || trimmed.length > 120) {
152	    return { ok: false, error: "Enter your name." };
153	  }
154	  const supabase = await createClient();
155	  const { error } = await supabase
156	    .from("profiles")
157	    .update({ full_name: trimmed })
158	    .eq("id", profile.id);
159	  if (error) return { ok: false, error: "Could not save your name." };
160	  revalidatePath("/account/settings");
161	  return { ok: true };
162	}
